command:
let companies = game.actors.filter(a => a.type === "company");

let html = `<h2>${game.i18n.localize("UTCF.Roll.Label")} ${game.i18n.localize("UTCF.Engagement.Label")}</h2><form><div class="form-field"><label>${game.i18n.localize("UTCF.Company.Label")}</label><select name="company_id">`;

companies.forEach(company => {
  html += `<option value="${company.id}">${company.name}</option>`
});

html += `</select></div></form>`;

new foundry.applications.api.DialogV2({
      window: {
        contentClasses: ["until-the-curtain-falls", "dialog-window"],
        title: `${game.i18n.localize("UTCF.Roll.Label")} ${game.i18n.localize("UTCF.Engagement.Label")}`
      },
      content: html,
      buttons: [
        {
          icon: '<i class="fas fa-check"></i>',
          label: game.i18n.localize('Roll'),
          action: 'add',
          callback: async (event, button, dialog) => {
            let company_id = button.form.elements.company_id.value;
            let company = game.actors.get(company_id);
            company.rollEngagementDialog();
          }
        },
        {
          icon: '<i class="fas fa-times"></i>',
          label: game.i18n.localize('Cancel'),
          action: 'cancel',
          callback: () => false
        }
      ]
    }, {}).render({force: true});
